style.css:
@-moz-document domain("roblox.com") {
/* full-screen original dessert photograph */
html,
body {
  background-color: #100e10 !important;
  background-image: url("https://i.postimg.cc/MT535q5m/Screenshot-%28336%29.png") !important;
  background-position: center center !important;
  background-size: cover !important;
  background-repeat: no-repeat !important;
  background-attachment: fixed !important;
  min-height: 100% !important;
}

/* remove Roblox home background layers */
.home-container,
.home-container .section,
.home-container .col-xs-12.container-header {
  background-color: transparent !important;
  background-image: none !important;
}

/* keep the gothic sweets visible */
h1, h2, h3, h4 {
  color: #eee9df !important;
}

/* dark chocolate buttons */
button {
  background-color: #211c21 !important;
  color: #eee9df !important;
  border: 1px solid #75666e !important;
  border-radius: 9px !important;
}
}
